        trabalha_hoje_antigo = _trabalha_pelo_esquema_antigo(jornada.paridade_ciclo, hoje)
        trabalha_hoje_novo = (hoje - jornada.data_inicio).days % 2 == 0
        if trabalha_hoje_novo == trabalha_hoje_antigo:
            continue  # já bate com o que o esquema antigo diz pra hoje, nada a fazer

        nova_data = jornada.data_inicio - timedelta(days=1)
        colide = FuncionarioJornada.objects.filter(
            funcionario_id=jornada.funcionario_id, data_inicio=nova_data,
        ).exclude(id=jornada.id).exists()
        if colide:
            continue  # caso raríssimo -- fica pra conferir manualmente depois
        jornada.data_inicio = nova_data
        jornada.save(update_fields=['data_inicio'])


